CREATE OR REPLACE FUNCTION public.get_next_letter_number()
RETURNS TEXT
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
  next_num BIGINT;
  next_code TEXT;
BEGIN
  UPDATE public.letter_number_counter
     SET last_number = last_number + 1
   WHERE id = 1
   RETURNING last_number INTO next_num;

  IF next_num IS NULL THEN
    RAISE EXCEPTION 'letter_number_counter row missing';
  END IF;

  next_code := 'ÃƒÆ’Ã†â€™Ãƒâ€¹Ã…â€œÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â®ÃƒÆ’Ã†â€™Ãƒâ€¹Ã…â€œÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â·ÃƒÆ’Ã†â€™Ãƒâ€¹Ã…â€œÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™Ãƒâ€¹Ã…â€œÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¨ ' || LPAD(next_num::TEXT, 4, '0');
  RETURN next_code;
END;
$$;
